// 5.1.1.1 - Input node: validate call notes/transcript text
const item = $input.item.json;
const errors = [];
if (!item.client_id) errors.push('client_id required');
if (!item.call_notes_text || item.call_notes_text.trim().length < 20) errors.push('call_notes_text required (min 20 chars)');

return [{
  json: {
    client_id: item.client_id,
    opportunity_id: item.opportunity_id || null,
    call_notes_text: (item.call_notes_text || '').trim(),
    source: item.source || 'manual',
    is_valid: errors.length === 0,
    validation_errors: errors.join('; ')
  }
}];

