// 5.1.1.4 - Output structure Code node: build the JSON schema matching Stage 27's mandatory field list
// (Opportunity ID, Framework Used, Assessment Fields, Decision, Assessed Date, Assessed By)
const input = $('Validate Input').item.json;

let bant = {};
try { bant = JSON.parse($('Ollama Extraction - BANT').item.json.response); }
catch (e) { bant = { parse_error: true, raw: $('Ollama Extraction - BANT').item.json.response }; }

let meddic = {};
try { meddic = JSON.parse($json.response); }
catch (e) { meddic = { parse_error: true, raw: $json.response }; }

return [{
  json: {
    client_id: input.client_id,
    opportunity_id: input.opportunity_id,
    framework_used: 'BANT+MEDDIC',
    assessment_fields: { bant, meddic },
    // Decision is deliberately NOT set here - per this master plan's AI-recommends/deterministic-decides
    // rule (§16.x), a human or a separately-defined rule sets 'Decision', extraction never does.
    decision: 'Pending Review',
    assessed_date: new Date().toISOString(),
    assessed_by: 'Ollama (' + (input.source || 'manual') + ') - pending human confirmation',
    extraction_had_parse_error: !!(bant.parse_error || meddic.parse_error)
  }
}];

parameters.query:
INSERT INTO qualification_records (client_id, framework, assessment, decision, assessed_by)
VALUES (
  {{ $json.client_id }},
  {{ JSON.stringify($json.framework_used) }},
  {{ JSON.stringify($json.assessment_fields) }}::jsonb,
  {{ JSON.stringify($json.decision) }},
  {{ JSON.stringify($json.assessed_by) }}
)
RETURNING id;
